import React, { useEffect, useState } from "react";
import { Spinner } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import { makeApiRequest } from "../../axiosService/ApiCall";
import NoaccessImage from "../../Assets/images/accessDeniedImage.png";

function NoAccess({ pageName, children }) {
  const [loading, setLoading] = useState(true);
  const [AccessadminType, setAdminType] = useState("");
  const [permissions, setPermissions] = useState({});
  const navigate = useNavigate();

  useEffect(() => {
    fetchPermissions();
  }, []);

  const fetchPermissions = async () => {
    try {
      const params = {
        url: "view-edit-GetData",
        method: "get",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };

      const res = await makeApiRequest(params);

      if (res.status === true && res.data) {
        setAdminType(res.data.admin_type);

        if (res.data.adminPermissions) {
          const permissionData = res.data.adminPermissions;
          setPermissions(permissionData);

          // ✅ If SubAdmin → check first allowed page
          if (res.data.admin_type === "SubAdmin") {
            const firstAllowedPage = findFirstAllowedPage(permissionData);
            if (firstAllowedPage) {
              navigate(`/dashboard/${firstAllowedPage}`);
            }
          }
        }
      }
    } catch (error) {
      console.error("Error fetching permissions:", error);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Helper function → find first page that has View = 1
  const findFirstAllowedPage = (permissions) => {
    const pageRoutes = {
      accounts: "user-list",
      pairList: "spot-pair-list",
      userRequest: "withdraw-request",
      transactionList: "user-transaction-list",
      orderHistory: "order-history",
      tradeHistory: "trade-history",
      cryptoFiat: "crypto-fiat-history",
      swapHistory: "swap-history",
      notification: "notification",
      siteSetting: "site-setting",
      cms: "terms-conditions",
      adminActivity: "admin-activity",
      supportTicket: "support-ticket",
    };

    for (const key in pageRoutes) {
      if (permissions[key]?.View == 1) {
        return pageRoutes[key];
      }
    }
    return null;
  };

  // ⏳ Loading Spinner
  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center vh-100">
        <Spinner animation="border" />
      </div>
    );
  }

  // 👑 SuperAdmin → full access
  if (AccessadminType == "SuperAdmin") {
    return <>{children}</>;
  }

  // 🛑 SubAdmin permission check
  const currentPermission = permissions?.[pageName]?.View;

  if (currentPermission === 1) {
    return <>{children}</>;
  } else {
    return (
      <div className="text-center col-6 mx-auto">
        <img
          src={NoaccessImage}
          alt="Access Denied"
          className="img-fluid"
          style={{ marginTop: "100px" }}
        />
        <h4 className="text-danger mt-3">Access Denied</h4>
      </div>
    );
  }
}

export default NoAccess;
